"""Bounded character-prefix-aware column block optimizer."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Construct and compare frequency and directed column-block orders."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the latest public row orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one cell with missing values represented by an empty string."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Score a fixed row-string collection by adjacent sorted-string LCPs."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _dependency_edges(columns, requested):
        """Convert named dependency pairs into unique integer directed edges."""
        locations = {}
        for i, column in enumerate(columns):
            locations.setdefault(str(column), []).append(i)

        edges = []
        seen = set()
        for left, right in requested or []:
            ls = locations.get(str(left), [])
            rs = locations.get(str(right), [])
            if len(ls) == 1 and len(rs) == 1 and ls[0] != rs[0]:
                edge = (ls[0], rs[0])
                if edge not in seen:
                    seen.add(edge)
                    edges.append(edge)
        return edges

    @classmethod
    def _constrained_order(cls, m, preference, columns, dependencies):
        """Topologically order columns while using preference as the tie-break."""
        edges = cls._dependency_edges(columns, dependencies)
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m
        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: i for i, column in enumerate(preference)}
        heap = [(rank[i], i) for i in range(m) if indegree[i] == 0]
        heapq.heapify(heap)
        answer = []

        while heap:
            _, node = heapq.heappop(heap)
            answer.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank[nxt], nxt))

        return answer if len(answer) == m else list(preference)

    @staticmethod
    def _statistics(text):
        """Compute per-column repeated character mass and total serialized length."""
        n, m = text.shape
        stats = []
        for col in range(m):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeat_mass = sum(
                len(value) * max(0, count - 1)
                for value, count in counts.items()
            )
            total = sum(len(value) * count for value, count in counts.items())
            stats.append((pair_mass, repeat_mass, total))
        return stats

    @staticmethod
    def _factor_codes(text):
        """Factorize each serialized column once into integer row codes."""
        n, m = text.shape
        codes = np.empty((n, m), dtype=np.int32)
        for col in range(m):
            mapping = {}
            next_code = 0
            for row in range(n):
                value = text[row, col]
                code = mapping.get(value)
                if code is None:
                    code = next_code
                    mapping[value] = code
                    next_code += 1
                codes[row, col] = code
        return codes

    @staticmethod
    def _merge_blocks(m, columns, col_merge):
        """Build indivisible requested merge blocks, retaining source order."""
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        locations = {}
        for i, column in enumerate(columns):
            locations.setdefault(str(column), []).append(i)

        for pair in col_merge or []:
            if len(pair) < 2:
                continue
            found = []
            for name in pair:
                pos = locations.get(str(name), [])
                if len(pos) == 1:
                    found.append(pos[0])
            if len(found) >= 2:
                root = find(found[0])
                for item in found[1:]:
                    other = find(item)
                    if other != root:
                        parent[other] = root

        groups = {}
        for i in range(m):
            groups.setdefault(find(i), []).append(i)
        return sorted(groups.values(), key=lambda block: min(block))

    @classmethod
    def _block_order(cls, text, codes, stats, blocks, seed_mode):
        """Greedily chain blocks using directed length-weighted continuation affinity."""
        n, m = text.shape
        block_of = {}
        for bi, block in enumerate(blocks):
            for col in block:
                block_of[col] = bi

        block_mass = []
        for block in blocks:
            block_mass.append(sum(stats[col][0] for col in block))

        seeds = sorted(
            range(len(blocks)),
            key=lambda b: (-block_mass[b], -len(blocks[b]), min(blocks[b])),
        )
        if seed_mode:
            seeds = sorted(
                seeds,
                key=lambda b: (
                    -(sum(stats[c][1] for c in blocks[b])),
                    -block_mass[b],
                    min(blocks[b]),
                ),
            )

        available = set(range(len(blocks)))
        result = []
        seed_limit = min(len(seeds), 48)

        while available:
            if not result:
                current = seeds[0] if seeds else min(available)
            else:
                current_block = blocks[result[-1]]
                predecessor = max(
                    current_block,
                    key=lambda c: (stats[c][0], stats[c][1], -c),
                )
                candidates = sorted(
                    available,
                    key=lambda b: (-block_mass[b], min(blocks[b])),
                )[:48]

                best = None
                for candidate in candidates:
                    successor = max(
                        blocks[candidate],
                        key=lambda c: (stats[c][0], stats[c][1], -c),
                    )
                    # Group by the predecessor code and accumulate repeated
                    # successor character mass within each group.
                    grouped = {}
                    for row in range(n):
                        key = int(codes[row, predecessor])
                        value_len = len(text[row, successor])
                        item = grouped.get(key)
                        if item is None:
                            grouped[key] = [1, value_len]
                        else:
                            item[0] += 1
                            item[1] += value_len
                    affinity = sum(
                        chars * count * (count - 1)
                        for count, chars in grouped.values()
                    )
                    key = (affinity, block_mass[candidate], -min(blocks[candidate]))
                    if best is None or key > best[0]:
                        best = (key, candidate)
                current = best[1] if best is not None else min(available)

            result.append(current)
            available.remove(current)

        flattened = []
        for bi in result:
            flattened.extend(sorted(blocks[bi]))
        return flattened

    @staticmethod
    def _serialize(text, orders):
        """Serialize each row according to its row-specific column permutation."""
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, strings):
        """Sort rows by serialized text and permute untouched source cells."""
        n, m = source.shape
        row_order = sorted(range(n), key=lambda r: (strings[r], r))
        output = np.empty((n, m), dtype=object)
        public = []

        for out_row, source_row in enumerate(row_order):
            order = orders[source_row]
            output[out_row, :] = [source[source_row, col] for col in order]
            public.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            output,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Compare a frequency baseline with three bounded directed block orders."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            result = df.copy()
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)
        for col in range(m):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        stats = self._statistics(text)
        codes = self._factor_codes(text)
        blocks = self._merge_blocks(m, list(df.columns), col_merge)

        baseline = [
            col for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]
        baseline = self._constrained_order(
            m, baseline, list(df.columns), one_way_dep
        )

        preferences = [baseline]
        for mode in (0, 1, 2):
            proposed = self._block_order(
                text, codes, stats, blocks, mode == 1
            )
            proposed = self._constrained_order(
                m, proposed, list(df.columns), one_way_dep
            )
            preferences.append(proposed)

        best_score = None
        best_orders = None
        best_strings = None

        for preference in preferences:
            orders = [preference[:] for _ in range(n)]
            strings = self._serialize(text, orders)
            score = self._trie_score(strings)
            if best_score is None or score > best_score:
                best_score = score
                best_orders = orders
                best_strings = strings

        result, public_orders = self._materialize(
            df, source, best_orders, best_strings
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

